#include <iostream>
#include <fstream>
#include <cmath>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("wektory.txt");
    int n;
    plik >> n;
    cout << fixed << setprecision(2);
    for (int i = 0; i < n; i++) {
        int x1, y1, x2, y2;
        plik >> x1 >> y1 >> x2 >> y2;
        double dot = x1 * x2 + y1 * y2;
        double len1 = sqrt((double)(x1 * x1 + y1 * y1));
        double len2 = sqrt((double)(x2 * x2 + y2 * y2));
        double cosA = dot / (len1 * len2);
        if (cosA > 1.0) cosA = 1.0;
        if (cosA < -1.0) cosA = -1.0;
        double kat = acos(cosA) * 180.0 / M_PI;
        cout << "u=(" << x1 << "," << y1 << ") v=(" << x2 << "," << y2
             << ") -> kat: " << kat << " stopni" << endl;
    }
    return 0;
}
```

**Wyjasnienie**: Kat miedzy wektorami obliczamy z iloczynu skalarnego i dlugosci wektorow. Funkcja acos zwraca wynik w radianach, wiec mnozumy przez 180/PI, zeby dostac stopnie.

Weryfikacja:
- u=(1,0) v=(0,1): dot=0, |u|=1, |v|=1, cos=0, kat=90.00
- u=(3,4) v=(4,3): dot=12+12=24, |u|=5, |v|=5, cos=24/25=0.96, kat=acos(0.96)=16.26
- u=(5,0) v=(-5,0): dot=-25, |u|=5, |v|=5, cos=-1, kat=180.00
- u=(6,0) v=(3,4): dot=18, |u|=6, |v|=5, cos=18/30=0.6, kat=acos(0.6)=53.13
